/* Web presentation materials derive from the existing prototype SSOT; no second brand palette. */
:root {
 --web-glass:color-mix(in oklch,var(--surface-deep) 88%,transparent);
 --web-bar:color-mix(in oklch,var(--sidebar) 94%,transparent);
 --web-soft-glass:color-mix(in oklch,var(--background) 67%,transparent);
 --web-line:color-mix(in oklch,var(--cyan) 24%,var(--border));
 --web-window-shadow:0 15px 45px color-mix(in oklch,var(--background) 65%,transparent);
 --web-wallpaper-overlay:linear-gradient(180deg,color-mix(in oklch,var(--background) 15%,transparent),color-mix(in oklch,var(--background) 10%,transparent) 40%,color-mix(in oklch,var(--background) 45%,transparent));
 --web-blue-icon:linear-gradient(150deg,color-mix(in oklch,var(--cyan) 65%,var(--primary)),var(--primary));
 --web-violet-icon:linear-gradient(145deg,var(--violet),color-mix(in oklch,var(--primary) 65%,var(--background)));
 --web-cyan-icon:linear-gradient(145deg,var(--cyan),color-mix(in oklch,var(--primary) 80%,var(--background)));
 --web-mint-icon:linear-gradient(145deg,var(--mint),color-mix(in oklch,var(--mint) 40%,var(--background)));
}
.web-workspace{--web-sidebar-width:190px;--web-header-height:62px;--web-footer-height:66px;position:relative;height:100dvh;min-height:0;isolation:isolate;overflow:hidden;font-size:12px;background:var(--background)}
